create or replace function public.notify_schedule_event() returns trigger language plpgsql security definer set search_path='' as $$ declare b uuid; key text:=gen_random_uuid()::text; begin for b in select id from public.transport_buses where (tg_op<>'DELETE' and ((new.bus_id is not null and id=new.bus_id) or (new.bus_id is null and route_id=new.route_id))) or (tg_op<>'INSERT' and ((old.bus_id is not null and id=old.bus_id) or (old.bus_id is null and route_id=old.route_id))) loop perform public.emit_bus_notice(b,key,'Schedule changed','A schedule for your assigned bus was updated. Contact the transport office for details.','schedule'); end loop; if tg_op='DELETE' then return old; end if; return new; end $$;
